      "version": "0.1.0",
      "description": "Evaluate answer quality using declared metrics and evaluation dependencies.",
      "destination": "src/{project_package}/rag/evaluation/answer_metrics.py",
      "install": "No additional packages required. Copy with: ragkit add <id>",
